mapper.select:

SELECT COUNT(*)
FROM TB_ROLE
WHERE ROLE_CODE = #{roleCode}

mapper.update:

    UPDATE TB_ROLE
    SET
        ROLE_NM = #{roleNm},
        CODE_DEC = #{roleNm},
        ROLE_GROUP = #{roleGroup}
	WHERE ROLE_CODE = #{roleCode}


    UPDATE TB_ROLE
    SET
        USE_YN = #{useYn}
	WHERE ROLE_CODE = #{roleCode}

mapper.select:

SELECT COUNT(*)
FROM TB_ROLE_GROUP
WHERE ROLE_GROUP = #{roleGroup}

mapper.update:

    UPDATE TB_ROLE_GROUP
    SET
        DESCRIPTION = #{description}
	WHERE ROLE_GROUP = #{roleGroup}


    UPDATE TB_ROLE_GROUP
    SET
        USE_YN = #{useYn}
	WHERE ROLE_GROUP = #{roleGroup}
